class CrestApiFsFlushTest : public ::testing::Test {
 protected:
  std::string m_root;

  void SetUp() override {
    m_root =
        "/tmp/crest_fs_flush_test_" +
        std::to_string(
            ::testing::UnitTest::GetInstance()->current_test_info()->line());
    std::filesystem::remove_all(m_root);
    std::filesystem::create_directories(m_root);
  }

  void TearDown() override { std::filesystem::remove_all(m_root); }

  std::string iovFile(const std::string &tagName) const {
    return m_root + "/tags/" + tagName + "/iovs.json";
  }

  static std::string readFile(const std::string &path) {
    std::ifstream in(path, std::ios::binary);
    std::stringstream buf;
    buf << in.rdbuf();
    return buf.str();
  }

  static void storeOne(CrestApiFs &api, const std::string &tagName,
                       uint64_t since) {
    StoreSetDto storeSet;
    storeSet.push_back(StoreDto(since, "", "payload " + std::to_string(since)));
    api.storeData(tagName, storeSet, "JSON", "test", "none", "1", 0);
  }
}

void SetUp() override {
    m_root =
        "/tmp/crest_fs_flush_test_" +
        std::to_string(
            ::testing::UnitTest::GetInstance()->current_test_info()->line());
    std::filesystem::remove_all(m_root);
    std::filesystem::create_directories(m_root);
  }

std::string iovFile(const std::string &tagName) const {
    return m_root + "/tags/" + tagName + "/iovs.json";
  }

static std::string readFile(const std::string &path) {
