TEST_F(CrestApiFsFlushTest, StoreLeavesNoTempFileAndValidJson) {
  CrestApiFs api(true, m_root);
  const std::string tagName = uniqueTagName("fs_flush");
  TagDto tag(tagName, "time", "flush test tag");
  api.createTag(tag);
  storeOne(api, tagName, 100);
  storeOne(api, tagName, 200);

  EXPECT_FALSE(std::filesystem::exists(iovFile(tagName) + ".tmp"));
  const nlohmann::json iovs = nlohmann::json::parse(readFile(iovFile(tagName)));
  ASSERT_TRUE(iovs.is_array());
  EXPECT_EQ(iovs.size(), 2u);
}

TEST_F(CrestApiFsFlushTest, FailedWriteThrowsAndKeepsOldFile) {
  CrestApiFs api(true, m_root);
  const std::string tagName = uniqueTagName("fs_flush");
  TagDto tag(tagName, "time", "flush test tag");
  api.createTag(tag);
  storeOne(api, tagName, 100);
  const std::string before = readFile(iovFile(tagName));

  // A directory at the temp path makes the open fail, also when run as root.
  const std::string tmpPath = iovFile(tagName) + ".tmp";
  std::filesystem::create_directory(tmpPath);
  EXPECT_THROW(storeOne(api, tagName, 200), CrestException);
  EXPECT_EQ(readFile(iovFile(tagName)), before);

  // A later flush (createTag of another tag) must not write the rows of the
  // store that threw.
  std::filesystem::remove(tmpPath);
  TagDto other(uniqueTagName("fs_flush_other"), "time", "other tag");
  api.createTag(other);
  EXPECT_EQ(readFile(iovFile(tagName)), before);
  EXPECT_EQ(api.getSize(tagName), 1);
}

TEST_F(CrestApiFsFlushTest, FailedRenameThrows) {
  CrestApiFs api(true, m_root);
  const std::string tagName = uniqueTagName("fs_flush");
  TagDto tag(tagName, "time", "flush test tag");
  api.createTag(tag);

  // A non-empty directory at iovs.json can't be replaced by a rename.
  std::filesystem::create_directories(iovFile(tagName) + "/blocker");
  try {
    storeOne(api, tagName, 100);
    FAIL() << "storeData did not throw";
  } catch (const CrestException &e) {
    EXPECT_NE(std::string(e.what()).find("cannot rename"), std::string::npos)
        << e.what();
  }
  EXPECT_TRUE(std::filesystem::is_directory(iovFile(tagName)));
}
